<script setup lang="ts">
/**
 * Token-styled scrollbar for a region that already scrolls (`design/components/scroll-area.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/scroll-area.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { computed, useId, useTemplateRef } from 'vue'

import * as zag from '@zag-js/scroll-area'
import { normalizeProps, useMachine } from '@zag-js/vue'

import { useDirection } from '@polymorph/vue'
import styles from '@polymorph/recipes/structure/scroll-area.module.css'

export type ScrollAreaOrientation = NonNullable<ScrollAreaProps['orientation']>

export type ScrollAreaType = NonNullable<ScrollAreaProps['type']>

export interface ScrollAreaProps {
  /**
   * Names the region for keyboard users once it overflows, as in CodeBlock. Required rather than
   * defaulted. The content identifies the region, but a default name would be in one fixed
   * language, and the app's language is unknown here.
   */
  label: string
  /**
   * Which axes may pan; `'both'` draws two rails and the corner.
   */
  orientation?: 'horizontal' | 'vertical' | 'both'
  type?: 'hover' | 'always'
}

defineOptions({ name: 'ScrollArea', inheritAttrs: false })

const props = withDefaults(defineProps<ScrollAreaProps>(), {
  orientation: 'vertical',
  type: 'always',
})
defineSlots<{ default: (props: Record<string, never>) => unknown }>()
const uid = useId()
const root = useTemplateRef<HTMLElement>('root')
const fades = computed(() => props.type === 'hover')
const documentDirection = useDirection(() => root.value)
const service = useMachine(
  zag.machine,
  computed(() => ({ id: uid, dir: documentDirection.value })),
)
const api = computed(() => zag.connect(service, normalizeProps))
const overflowing = computed(() => api.value.hasOverflowX || api.value.hasOverflowY)
</script>

<template>
  <div ref="root" v-bind="api.getRootProps()" :class="styles.root" data-member="scroll-area">
    <div
      v-bind="api.getViewportProps()"
      :class="styles.viewport"
      :style="{
        overflowX: orientation === 'vertical' ? 'hidden' : 'scroll',
        overflowY: orientation === 'horizontal' ? 'hidden' : 'scroll',
        scrollbarWidth: 'none',
      }"
      :tabindex="overflowing ? 0 : undefined"
      :role="overflowing ? 'region' : undefined"
      :aria-label="overflowing ? label : undefined"
    >
      <div v-bind="api.getContentProps()">
        <slot />
      </div>
    </div>
    <template v-if="orientation === 'both' || orientation === 'vertical'">
      <div
        v-if="api.hasOverflowY"
        v-bind="api.getScrollbarProps({ orientation: 'vertical' })"
        :class="[styles.rail, fades ? styles.hover : undefined, !fades ? styles.always : undefined]"
        aria-hidden="true"
        :data-state="
          fades
            ? api.getScrollbarState({ orientation: 'vertical' }).hovering ||
              api.getScrollbarState({ orientation: 'vertical' }).scrolling
              ? 'visible'
              : 'hidden'
            : undefined
        "
      >
        <div v-bind="api.getThumbProps({ orientation: 'vertical' })" :class="styles.thumb" />
      </div>
    </template>
    <template v-if="orientation === 'both' || orientation === 'horizontal'">
      <div
        v-if="api.hasOverflowX"
        v-bind="api.getScrollbarProps({ orientation: 'horizontal' })"
        :class="[styles.rail, fades ? styles.hover : undefined, !fades ? styles.always : undefined]"
        aria-hidden="true"
        :data-state="
          fades
            ? api.getScrollbarState({ orientation: 'horizontal' }).hovering ||
              api.getScrollbarState({ orientation: 'horizontal' }).scrolling
              ? 'visible'
              : 'hidden'
            : undefined
        "
      >
        <div v-bind="api.getThumbProps({ orientation: 'horizontal' })" :class="styles.thumb" />
      </div>
    </template>
    <div
      v-if="orientation === 'both'"
      v-bind="api.getCornerProps()"
      :class="styles.corner"
      aria-hidden="true"
    />
  </div>
</template>
